Method.Implementation:
   Set tRS = ##class(%ResultSet).%New("%SYS.Namespace:List")
  Set tSC = tRS.Execute()
  For {
            Quit:'tRS.Next()
            set nmSp = tRS.Get("Nsp")

            try
            {
	          set $NAMESPACE = nmSp


			  $$$LOGINFO( $NAMESPACE _ "- PurgeEnsResponseTask")

			  Do ..PurgeEmptyEnsResponse()

			  // Get MIN from Header table
			  set getMsgHdrMinVal = "SELECT MIN (MessageBodyId) as msgHdrMinVal FROM Ens.MessageHeader where MessageBodyClassName = ?" 
			  SET msgHdrStatement = ##class(%SQL.Statement).%New()
			  SET qStatus = msgHdrStatement.%Prepare(getMsgHdrMinVal)
			  IF qStatus'=1 {$$$LOGERROR( "%Prepare failed: " _ getMsgHdrMinVal) QUIT}

			  // Get MIN from Response table
			  set getRespMinVal = "SELECT MIN (ID) as minRespVal FROM Ens.Response where x__classname = ?" 
			  SET tStatementResp = ##class(%SQL.Statement).%New()
			  SET qStatus = tStatementResp.%Prepare(getRespMinVal)
			  IF qStatus'=1 {$$$LOGERROR( "%Prepare failed: " _ getRespMinVal) QUIT}


			 try {
					 // GET all classnames from Ens.Response
					 SET myquery = " SELECT distinct x__classname as origClsNm, substring(x__classname, CHARINDEX('~IHC', x__classname) +1, LEN(x__classname) -2) as clsNm FROM Ens.Response where x__classname like '%IHC%'"
					 // WRITE !, myquery
					 SET tStatement = ##class(%SQL.Statement).%New()
					 // Write !, "Prepare query"
					 SET qStatus = tStatement.%Prepare(myquery)
					 IF qStatus'=1 {$$$LOGERROR( "%Prepare failed: " _ myquery) QUIT}


					 set rset = tStatement.%Execute()
					 // WRITE !, "Execute: " _ rset.%SQLCODE 
					 While (rset.%Next()) {
						 // WRITE !, "# " _ rset.%ROWCOUNT
						 set nm = $ZSTRIP(rset.%Get("clsNm"), "*", "~")

					    // FIND LAST . and get last part as table, replace . with _ in first part to get schema
				 		SET lastPos=$LENGTH(nm)+2-$FIND($REVERSE(nm),".")
						set tblNm = $EXTRACT(nm, lastPos+1, *)
						set schema = $REPLACE($EXTRACT(nm, 1, lastPos-1), ".", "_")
						set origClsNm = rset.%Get("origClsNm")
						 // Write " --- " _ nm _ "- " _ schema _"." _ tblNm _ ", orig name: " _ origClsNm
					     // ----
					     		set rsetResp = tStatementResp.%Execute(origClsNm)
								 // WRITE !, "Execute: " _ rsetResp.%SQLCODE 
								 While (rsetResp.%Next()) {
									 set minRespVal = rsetResp.%Get("minRespVal")
								     // Write ", Min value in Ens.Response for " _ origClsNm _ ": " _ minRespVal
								 }

					     		 set msgHdrResSet = msgHdrStatement.%Execute(nm)
								 // WRITE !, "Execute: " _ msgHdrResSet.%SQLCODE 
								 While (msgHdrResSet.%Next()) {
									 set msgHdrMinVal = msgHdrResSet.%Get("msgHdrMinVal")
								     // Write ", Min value in Ens.MessageHeader for " _ nm _ " : " _ msgHdrMinVal
								 }
							 	 $$$LOGINFO("Min value in Ens.MessageHeader for " _ nm _ " : " _ msgHdrMinVal _ ", Min value in Ens.Response for class: " _ origClsNm _ ": " _ minRespVal)

								 if (($L(msgHdrMinVal) > 0) && (msgHdrMinVal > minRespVal))
								 {
									  Do ##class(IHC.ITF.ITFCOMMON.Util.PurgeClasses).PurgeTask($NAMESPACE, schema, tblNm, msgHdrMinVal)

									  set delRespTable = "DELETE FROM Ens.Response where x__classname = '" _ origClsNm _ "' and ID < " _  msgHdrMinVal
									  SET tStatement3 = ##class(%SQL.Statement).%New()
									  SET qStatus = tStatement3.%Prepare(delRespTable)
									  IF qStatus'=1 {$$$LOGERROR(  "DELETE %Prepare failed: " _ delRespTable) DO $System.Status.DisplayError(qStatus) QUIT}
									  set rset3 = tStatement3.%Execute()
									  $$$LOGINFO( "DELETE Execute: " _ rset3.%SQLCODE  _ " - " _ delRespTable _ ", Count: " _ rset3.%ROWCOUNT)
								 }
								 elseif ($L(msgHdrMinVal) <= 0)
								 {
									  set delRespTable = "DELETE FROM Ens.Response where x__classname = '" _ origClsNm _ "'"
									  SET tStatement3 = ##class(%SQL.Statement).%New()
									  SET qStatus = tStatement3.%Prepare(delRespTable)
									  IF qStatus'=1 {$$$LOGERROR(  "DELETE %Prepare failed: " _ delRespTable) DO $System.Status.DisplayError(qStatus) QUIT}
									  set rset3 = tStatement3.%Execute()
									  $$$LOGINFO( "DELETE Execute: " _ rset3.%SQLCODE  _ " - " _ delRespTable _ ", Count: " _ rset3.%ROWCOUNT)

								 }
					     // ----
					 }


				  // Write !, " ------ " 

			 } catch err
			 {
				 $$$LOGERROR( "Exception in running purge: " _ err.Code _ ", " _ err.Location  )
			 }
		 } catch exp
		 {
			 WRITE !, "Can't run Task in namespace: " _ nmSp _ ", " _ exp.Code _ ", " _ exp.Location 
		 }
  }
 return $$$OK

	 try
            {

	            set getMaxVal2 = "select count(ID) as cntBd from Ens.MessageBody where x__className = '~Ens.Response~'" 
  				SET tStatement2 = ##class(%SQL.Statement).%New()
  				SET qStatus = tStatement2.%Prepare(getMaxVal2)
  				IF qStatus'=1 {WRITE !, "  SELECT %Prepare failed:" QUIT}
  				set rset2 = tStatement2.%Execute()
				// WRITE !, "Execute: " _ rset2.%SQLCODE 
				While (rset2.%Next()) {
						 set maxVal = rset2.%Get("cntBd")
					     // Write ", count in Ens.MessageBody : " _ maxVal
				}
				&sql(SELECT MIN(ID) INTO :minVal from Ens.Response where x__className = '~Ens.Response~')
				&sql(SELECT MAX(ID) INTO :maxVal from Ens.Response)
				SET delStatement = ##class(%SQL.Statement).%New()
				$$$LOGINFO("Purge ~Ens.Response~ from " _ minVal _ " to " _ maxVal)
				SET val = minVal + 1000000
				DO 
				{

					set delMaxVal = "DELETE  %NOLOCK from Ens.Response where x__className = '~Ens.Response~' AND ID < " _ val 

	  				SET qStatus = delStatement.%Prepare(delMaxVal)
	  				IF qStatus'=1 {WRITE !, "  SELECT %Prepare failed for: " _ delMaxVal QUIT}
	  				set rset = delStatement.%Execute()
					// $$$LOGINFO( delMaxVal _ ", SQLCODE: " _ rset.%SQLCODE _ ", count: " _ rset.%ROWCOUNT)

					if ( val >= maxVal)
					{
						set val = maxVal + 1
					}
					elseif ( (val + 1000000) > maxVal)
					{
						set val = maxVal
					}
					else
					{
						set val = val + 1000000
					}
				} while (val <= maxVal)
				/*
				set rset2 = tStatement2.%Execute()
				WRITE !, "Execute: " _ rset2.%SQLCODE 
				While (rset2.%Next()) {
						 set maxVal = rset2.%Get("cntBd")
					     Write !, "After Delete, Count in Ens.MessageBody : " _ maxVal
				}

				&sql(SELECT COUNT(ID) INTO :cnt from Ens.Response)
				Write ", count in Ens.Response : " _ cnt
				*/


            } catch err
            {
	            $$$LOGERROR( "EXception in PurgeEmptyEnsResponse: " _ err)
            }
            return $$$OK
